import fs from "fs";
const FILE = new URL("../index.html", import.meta.url).pathname;
let src = fs.readFileSync(FILE, "utf8");

// v0.48 §4 — ZONE 1 becomes one plain-language sentence per building. Every number
// that used to live in these strings is now generated by effectLines() from the same
// fields computeRates()/computeCaps() read.
