// v0.48 §4 — eight per-copy constants that were literals at their point of use and
// prose at their point of display. Now fields, read by both.
const FIELDS = {
  bardsHearth: "audience: 0.05",
  poroPasture: "eatCut: 0.003, eatCutLimit: 0.5",
  tradeDock: "tradeBoost: 0.02",
  workshop: "craftBoost: 0.06",
  hunterLodge: "campBoost: 0.15",
  chembarrel: "sumpBoost: 0.25",
  hexgateBuilding: "tradeBoost: 0.12"
};

function valueEnd(text, i) {
  let depth = 0, q = null;
  for (; i < text.length; i++) {
    const c = text[i], p = text[i - 1];
    if (q) { if (c === q && p !== "\\") q = null; continue; }
    if (c === "/" && text[i + 1] === "/") { i = text.indexOf("\n", i); if (i < 0) break; continue; }
    if (c === '"' || c === "'") { q = c; continue; }
    if (c === "[" || c === "{" || c === "(") depth++;
    else if (c === "]" || c === "}" || c === ")") { if (depth === 0) return i; depth--; }
    else if (c === "," && depth === 0) return i;
  }
  throw new Error("no value end");
}
// End of the object literal that starts at `open` (index of its "{").
function objEnd(text, open) {
  let depth = 0, q = null;
  for (let i = open; i < text.length; i++) {
    const c = text[i], p = text[i - 1];
    if (q) { if (c === q && p !== "\\") q = null; continue; }
    if (c === "/" && text[i + 1] === "/") { i = text.indexOf("\n", i); if (i < 0) break; continue; }
    if (c === '"' || c === "'") { q = c; continue; }
    if (c === "{" || c === "[" || c === "(") depth++;
    else if (c === "}" || c === "]" || c === ")") { depth--; if (depth === 0) return i; }
  }
  throw new Error("unbalanced object");
}

const a = src.indexOf("var BUILDINGS = [");
const b = src.indexOf("\nvar JOBS");
let body = src.slice(a, b);
let n = 0, missing = [];
for (const id of Object.keys(EFFECT)) {
  const anchor = body.indexOf('{ id: "' + id + '",');
  if (anchor < 0) { missing.push(id); continue; }
  const end = objEnd(body, anchor);
  const ek = body.indexOf("effect:", anchor);
  if (ek < 0 || ek > end) { missing.push(id + " (no effect)"); continue; }
  const ve = valueEnd(body, ek + 7);
  body = body.slice(0, ek) + "effect: " + JSON.stringify(EFFECT[id]) + body.slice(ve);
  n++;
  if (FIELDS[id]) {
    const e2 = objEnd(body, body.indexOf('{ id: "' + id + '",'));
    body = body.slice(0, e2).replace(/\s*$/, "") + ",\n    " + FIELDS[id] + " " + body.slice(e2);
  }
}
src = src.slice(0, a) + body + src.slice(b);
fs.writeFileSync(FILE, src);
console.log("rewrote", n, "building effect strings;", Object.keys(FIELDS).length, "field additions");
if (missing.length) { console.log("MISSING: " + missing.join(", ")); process.exit(1); }
